async function analyze(){
 if(!state.area||!state.month)return;
 const started=performance.now(),run=++state.run;state.water=$('input[name=water]:checked').value;if($('#planning-dialog').open)$('#planning-dialog').close();show('loading');
 const steps=$$('#loading-steps li');steps.forEach(n=>n.classList.remove('done'));$('#loading-status').textContent=tr('Working on your device…');$('#loading-status').classList.remove('error-text');
 $('#loading-context').textContent=(state.lang==='th'?areas.find(a=>a.id===state.area).thai:areas.find(a=>a.id===state.area).name)+' · '+monthName(state.month-1)+' '+displayYear();
 try{
 await frame();if(run!==state.run)return;
 for(const a of areas)if(M[a.id].meta.dailyRecords!==10958)throw Error('The weather data could not be checked. Please try again.');steps[0].classList.add('done');
 await frame();if(run!==state.run)return;
 const selected=engines[state.area].compare({month:state.month,water:state.water,location:state.area});state.results={[state.area]:selected};steps[1].classList.add('done');
 await frame();if(run!==state.run)return;
 for(const a of areas)if(a.id!==state.area)state.results[a.id]=engines[a.id].compare({month:state.month,water:state.water,location:a.id});
 steps[2].classList.add('done');$('#loading-status').textContent=tr('Your crop map is ready.');
 // Briefly retain the completed status so the loading-to-results transition is readable.
 await new Promise(r=>setTimeout(r,Math.max(200,2600-(performance.now()-started))));if(run!==state.run)return;
 state.active=state.area;setSheet(false);updateResults();show('map');updatePins();if(tourActive){tourStage='results';renderTour();}
 }catch(error){$('#loading-status').textContent=state.lang==='th'?'ตรวจสอบข้อมูลอากาศไม่ได้ โปรดลองอีกครั้ง':error.message;$('#loading-status').classList.add('error-text');}
}
$('#analyze-button').addEventListener('click',analyze);
$$('input[name=water]').forEach(input=>input.addEventListener('change',()=>{$('#analyze-button').disabled=!state.month;if(tourActive&&tourStage==='water'){tourStage='ready';renderTour();}}));
