function reasonInLanguage(text,c){
 if(state.lang!=='th')return text;
 if(text.startsWith('In ')&&text.includes('similar past seasons, total rain was below')){const n=text.match(/In (\d+) of the (\d+)/);return `ใน ${n?.[1]||''} จาก ${n?.[2]||''} ฤดูกาลที่ผ่านมา ปริมาณฝนรวมต่ำกว่าเกณฑ์น้ำพื้นฐานของพืชชนิดนี้`;}
 if(text===`The reference weather point is ${Math.round(M[state.active].meta.gridElevationM)} m above sea level; this crop’s guide calls for sites above ${c.elevationMin} m. Your farm may be higher, so check its exact elevation.`)return `จุดอ้างอิงสภาพอากาศอยู่สูงจากระดับน้ำทะเล ${Math.round(M[state.active].meta.gridElevationM)} เมตร แต่คำแนะนำของพืชนี้ระบุว่าควรปลูกที่สูงกว่า ${c.elevationMin} เมตร ฟาร์มของคุณอาจอยู่สูงกว่า โปรดตรวจสอบระดับความสูงจริง`;
 return tr(text);
}
function setupMap(){
 if(!globalThis.L){$('#map-error').hidden=false;return;}
 if(!map){
  map=L.map('map',{zoomControl:false,scrollWheelZoom:true,touchZoom:true,doubleClickZoom:true,minZoom:4,maxZoom:9}).setView([15.2,101.1],5);
  const countryRings=globalThis.THAILAND_COUNTRY_OUTLINE.map(ring=>ring.map(([lng,lat])=>[lat,lng]));
  L.geoJSON(globalThis.THAILAND_DISTRICTS,{interactive:false,style:{color:'transparent',weight:0,fillColor:'#daddd8',fillOpacity:1,stroke:false}}).addTo(map);
  window.thailandBorder=L.polyline(countryRings,{color:'#a8b7a6',weight:1.2,opacity:1,interactive:false,lineJoin:'round',lineCap:'round'}).addTo(map);
  window.resultProvinceOutlines={};window.provinceLabels={};
  const labels={'chiang-mai-valley':'Chiang Mai','bang-klam':'Songkhla','phunphin':'Surat Thani'},thaiNames={'chiang-mai-valley':'จังหวัดเชียงใหม่','bang-klam':'จังหวัดสงขลา','phunphin':'จังหวัดสุราษฎร์ธานี'};
  for(const a of areas){
   const geometry=globalThis.AREA_BOUNDARIES?.[a.id];
   if(geometry)boundaries[a.id]=L.geoJSON(geometry,{style:{color:'transparent',weight:0,fillColor:fitShade(state.results[a.id]?.crops?.[0]?.rating),fillOpacity:1,stroke:false},onEachFeature:(_f,layer)=>layer.on('click',()=>chooseMapArea(a.id,false))}).addTo(map);
   const paths=globalThis.PROVINCE_OUTLINES?.[a.id]?.map(path=>path.map(([lng,lat])=>[lat,lng]));
   if(paths)window.resultProvinceOutlines[a.id]=L.polyline(paths,{color:'#315a3f',weight:2.2,opacity:1,interactive:false,lineJoin:'round',lineCap:'round'}).addTo(map);
   const title=state.lang==='th'?thaiNames[a.id]:labels[a.id],icon=L.divIcon({className:'province-map-label'+(a.id===state.active?' selected':''),html:`<span>${title}</span>`,iconSize:[120,28],iconAnchor:[60,14]});
   window.provinceLabels[a.id]=L.marker(a.point,{icon,keyboard:true,title,alt:title}).addTo(map).on('click',()=>chooseMapArea(a.id,false));
  }
  map.attributionControl.addAttribution('<a href="https://www.geoboundaries.org" target="_blank" rel="noopener">geoBoundaries</a>');
  fitMap();
 }
 syncMapMode();updatePins();
}
function fitMap(){if(map)map.fitBounds([[5.5,97.2],[20.6,105.8]],{paddingTopLeft:[12,105],paddingBottomRight:[12,185],maxZoom:5});}
