function updatePins(){
 if(!map)return;
 const labels={'chiang-mai-valley':'Chiang Mai','bang-klam':'Songkhla','phunphin':'Surat Thani'},thaiNames={'chiang-mai-valley':'จังหวัดเชียงใหม่','bang-klam':'จังหวัดสงขลา','phunphin':'จังหวัดสุราษฎร์ธานี'};
 for(const a of areas){
  const r=state.results[a.id];
  if(r&&boundaries[a.id])boundaries[a.id].setStyle({color:'transparent',weight:0,fillColor:a.id===state.active?'#4f8243':fitShade(r.crops?.[0]?.rating),stroke:false,fillOpacity:a.id===state.active?1:.74});
  if(window.resultProvinceOutlines?.[a.id])window.resultProvinceOutlines[a.id].setStyle({color:a.id===state.active?'#173f31':'#91a58b',weight:a.id===state.active?3.4:1.7,opacity:1});
  if(window.provinceLabels?.[a.id]){const title=state.lang==='th'?thaiNames[a.id]:labels[a.id],icon=L.divIcon({className:'province-map-label'+(a.id===state.active?' selected':''),html:`<span>${title}</span>`,iconSize:[120,28],iconAnchor:[60,14]});window.provinceLabels[a.id].setIcon(icon);window.provinceLabels[a.id].options.title=title;}
 }
}
