const context=document.modelContext;if(context?.registerTool){const lifetime=new AbortController();try{Promise.resolve(context.registerTool({name:'explore_crop_area',title:'Explore crop ideas',description:'Choose a supported area, planting month, and water source; see the top three climate-fit crop ideas on the map.',inputSchema:{type:'object',properties:{area:{type:'string',enum:areas.map(a=>a.id)},month:{type:'integer',minimum:1,maximum:12},water:{type:'string',enum:['rainfed','irrigated']}},required:['area','month','water'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||!M[input.area]||!Number.isInteger(input.month)||input.month<1||input.month>12||!['rainfed','irrigated'].includes(input.water)||Object.keys(input).some(k=>!['area','month','water'].includes(k)))throw Error('Choose a supported area, month, and water source.');selectArea(input.area);selectMonth(input.month);$(`input[name=water][value="${input.water}"]`).checked=true;await analyze();const r=state.results[state.area];return {area:state.area,month:state.month,crops:r.crops.slice(0,3).map(c=>({name:c.name,status:c.status,rating:c.rating}))};}},{signal:lifetime.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}catch{}}
